def refill(self, now):
    elapsed = now - self.last
    if elapsed <= 0:
        return
    # Advance the clock regardless of how little time passed. Tokens are
    # fractional, so frequent small intervals accumulate instead of being
    # truncated to zero and lost.
    self.last = now
    if self.tokens < self.capacity:
        self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)

